    double x2 = nodes[n2][0], y2 = nodes[n2][1];
    double x3 = nodes[n3][0], y3 = nodes[n3][1];

    // Compute area
    double area = 0.5 * std::abs((x2-x1)*(y3-y1) - (x3-x1)*(y2-y1));
    if (area < 1e-15) {
        for (auto& v : kij_out) v = 0.0;
        return;
