    K02 << ke_full(0,2), ke_full(0,3),
           ke_full(1,2), ke_full(1,3);
    Eigen::Matrix<double, 2, 2> K02r = T.transpose() * K02 * T;
    ke_rot(0,2) = K02r(0,0); ke_rot(0,3) = K02r(0,1);
    ke_rot(1,2) = K02r(1,0); ke_rot(1,3) = K02r(1,1);

    // Block (0,4): A-C
