    K04 << ke_full(0,4), ke_full(0,5),
           ke_full(1,4), ke_full(1,5);
    Eigen::Matrix<double, 2, 2> K04r = T.transpose() * K04 * T;
    ke_rot(0,4) = K04r(0,0); ke_rot(0,5) = K04r(0,1);
    ke_rot(1,4) = K04r(1,0); ke_rot(1,5) = K04r(1,1);

    // Block (2,0): B-A
    Eigen::Matrix<double, 2, 2> K20;
    K20 << ke_full(2,0), ke_full(2,1),
           ke_full(3,0), ke_full(3,1);
    Eigen::Matrix<double, 2, 2> K20r = T.transpose() * K20 * T;
    ke_rot(2,0) = K20r(0,0); ke_rot(2,1) = K20r(0,1);
    ke_rot(3,0) = K20r(1,0); ke_rot(3,1) = K20r(1,1);

    // Block (2,2): B-B
    Eigen::Matrix<double, 2, 2> K22;
    K22 << ke_full(2,2), ke_full(2,3),
           ke_full(3,2), ke_full(3,3);
    Eigen::Matrix<double, 2, 2> K22r = T.transpose() * K22 * T;
    ke_rot(2,2) = K22r(0,0); ke_rot(2,3) = K22r(0,1);
    ke_rot(3,2) = K22r(1,0); ke_rot(3,3) = K22r(1,1);

