    Eigen::Matrix<double, 2, 2> K24r = T.transpose() * K24 * T;
    ke_rot(2,4) = K24r(0,0); ke_rot(2,5) = K24r(0,1);
    ke_rot(3,4) = K24r(1,0); ke_rot(3,5) = K24r(1,1);

