// Assemble triangle stiffness into global 8x8 matrix
// tri_nodes: list of 3 node indices in quad (0,1,2,3)
// quad_to_global: maps quad node index to global DOF start: [0,2,4,6] for u,v ordering
void sma1b(const std::vector<double>& kij, const std::vector<int>& tri_nodes,
           const std::vector<int>& quad_to_global, Eigen::Matrix<double, 8, 8>& K) {
    // kij is 36-element vector = 6x6
    Eigen::Matrix<double, 6, 6> ke;
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            ke(i,j) = kij[i*6 + j];
        }
    }

    // Map triangle nodes to global DOF indices
    // Each node has 2 DOFs: u then v
    std::vector<int> dof_map;
    for (int n : tri_nodes) {
        int base = quad_to_global[n];
        dof_map.push_back(base);     // u
        dof_map.push_back(base+1); // v
    }

    // Assemble: K[dof_map[i], dof_map[j]] += ke(i,j)
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            int gi = dof_map[i];
            int gj = dof_map[j];
            if (gi < 8 && gj < 8) {
                K(gi, gj) += ke(i, j);
            }
        }
    }
}

// Main CQUAD4 stiffness via triangle decomposition
Eigen::Matrix<double, 8, 8> compute_cquad4_stiffness_tri(
    const std::vector<std::vector<double>>& nodes,
    double E, double nu, double t) {

    // Compute element orientation: angle of edge 0->1
    double dx = nodes[1][0] - nodes[0][0];
    double dy = nodes[1][1] - nodes[0][1];
    double len = std::sqrt(dx*dx + dy*dy);
    double cosang = (len > 1e-15) ? dx/len : 1.0;
    double sinang = (len > 1e-15) ? dy/len : 0.0;

    // Quad node order: 0,1,2,3 → map to DOF starts: u0,v0,u1,v1,u2,v2,u3,v3 → [0,2,4,6]
    std::vector<int> quad_to_global = {0, 2, 4, 6};

    // Two triangles: (0,1,2) and (0,2,3)
    std::vector<std::vector<int>> triangles = {{0,1,2}, {0,2,3}};

    Eigen::Matrix<double, 8, 8> K = Eigen::Matrix<double, 8, 8>::Zero();

    std::vector<double> kij(36, 0.0);
    for (const auto& tri : triangles) {
        ktrmem(0, tri[0], tri[1], tri[2], nodes, E, nu, t, cosang, sinang, kij);
        sma1b(kij, tri, quad_to_global, K);
    }

    return K;
}

